#!/usr/bin/env python3
"""embed_cursor - embed cursor.png as a C++ byte array.

Writes kernel/input/cursor_png_data.cc containing the raw PNG bytes so the
kernel can decode the cursor sprite at boot via codec_decode (PNG codec).
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "cursor.png"
OUT = ROOT / "kernel" / "input" / "cursor_png_data.cc"


def main() -> int:
    blob = SRC.read_bytes()
    if blob[:8] != b"\x89PNG\r\n\x1a\n":
        print(f"error: {SRC} is not a PNG file")
        return 1
    lines = [
        "// Generated by tools/embed_cursor.py - do not edit.",
        f"// Raw cursor.png bytes, {len(blob)} bytes (RGBA PNG sprite).",
        "namespace hype::input {",
        "",
        "extern const unsigned char cursor_png_data[] = {",
    ]
    for i in range(0, len(blob), 12):
        chunk = ", ".join(f"0x{b:02X}" for b in blob[i : i + 12])
        lines.append(f"    {chunk},")
    lines += [
        "};",
        f"extern const unsigned int cursor_png_data_size = {len(blob)};",
        "",
        "}  // namespace hype::input",
        "",
    ]
    OUT.write_text("\n".join(lines))
    print(f"wrote {OUT} ({len(blob)} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
